In this paper, we consider the problem of solving a system of nonlinear equations:
%
\begin{equation}\label{eq:monotone}
  \vF(\vz) = 0,
  %
\end{equation}

where $\vF : \reals^d \rightarrow \reals^d$ is a continuously differentiable operator.


\begin{assumption}\label{assum:strong_monotone}  
The operator $\vF$ is $\mu$-strongly monotone, i.e., $\langle \vF(\vz)-\vF(\vz'), \vz-\vz' \rangle \geq \mu \|\vz-\vz'\|^2$,  $\forall \vz,\vz' \in \reals^d$. 
   %
\end{assumption}

\begin{assumption}\label{assum:monotone}  
  $\vF$ is monotone, i.e., $\langle \vF(\vz)-\vF(\vz'), \vz-\vz' \rangle \geq 0$,  $\forall \vz,\vz' \in \reals^d$. 
  %
\end{assumption}

Note that under Assumption~\ref{assum:strong_monotone}, Problem \eqref{eq:monotone} has a unique solution, which we denote by $\vz^*$ throughout the paper.
Moreover, Assumption~\ref{assum:monotone} can be regarded as a special case of Assumption~\ref{assum:strong_monotone} by setting $\mu=0$. Therefore, we will sometimes use this observation to present our results in both settings in a united manner, avoiding unnecessary repetition. In addition, we make the following two assumptions that the operator $\vF$ and its Jacobian are Lipschitz. 


\begin{assumption}\label{assum:operator_lips}
The operator $\vF$ is $L_1$-Lipschitz, i.e., $\|\vF(\vz)-\vF(\vz')\| \leq L_1\|\vz-\vz'\|$, $\forall \vz,\vz' \in \reals^d$.  
 %
\end{assumption}

\begin{assumption}\label{assum:jacobian_lips}
  The Jacobian of $\vF$ is $L_2$-Lipschitz, i.e., $\|\nabla \vF(\vz)-\nabla \vF(\vz')\|_{\op} \leq L_2\|\vz-\vz'\|$, $\forall \vz,\vz'\in \reals^d$, where $\|\mA\|_{\op} \mydef \sup_{\|\vz\| = 1} \|\mA \vz\|$. 
  %
\end{assumption}

\myalert{{Minimization.}} As a special instance of Problem \eqref{eq:monotone}, consider the unconstrained minimization problem 
\begin{equation}\label{eq:minimization}
  \min_{\vz \in \reals^d} f(\vz),
\end{equation}

%
where $f\!:\! \reals^d\! \rightarrow \!\reals$ is a (strongly) convex function. By the first-order optimality condition, the optimal solution of \eqref{eq:minimization} satisfies the nonlinear equation $\nabla f(\vz) = 0$. Thus, in this case, $\vF$ is  the gradient operator, i.e., $\vF(\vz) = \nabla f(\vz)$, and its Jacobian is the Hessian matrix of $f$, i.e., $\nabla \vF(\vz) = \nabla^2 f(\vz)$. In particular, we observe that the Jacobian is a symmetric matrix, which allows us to simplify the conditions in Lemma~\ref{lem:jacobian}. Specifically, under Assumptions~\ref{assum:strong_monotone} and~\ref{assum:operator_lips},  $\nabla \vF$ belongs to the set $\{\mA \in \mathbb{S}^d\!: \mu \mI \preceq\! \mA\! \preceq L\mI\}$. Meanwhile, under Assumptions~\ref{assum:monotone} and~\ref{assum:operator_lips}, it belongs to the set $\{\mA \in \mathbb{S}^d\!: 0 \preceq\! \mA\! \preceq L\mI\}$. As discussed in Section~\ref{subsec:nonlinear_eqs}, in our method, we ensure that the Jacobian approximation matrix stays symmetric and positive semidefinite, which is a key property for the efficient implementation of the subroutines.


\myalert{Minimax optimization.} Another important instance of Problem \eqref{eq:monotone} is the unconstrained minimax optimization problem 
\begin{equation}\label{eq:minimax}
  \min_{\vx \in \reals^m} \max_{\vy \in \reals^n} f(\vx,\vy),
\end{equation}

%
where $f$ is (strongly) convex with respect to $\vx$ and (strongly) concave with respect to $\vy$. To reformulate this problem as \eqref{eq:monotone}, we define the saddle point operator as $\vF(\vz) = (\nabla f_{\vx}(\vx,\vy),-\nabla f_{\vy}(\vx,\vy)) \in \reals^{m+n}$, where $\vz = (\vx,\vy) \in \reals^{m+n}$. Indeed, finding a solution of $\vF(\vz)$ is equivalent to finding a stationary point of the minimax problem, which is the optimal solution. In this case, the Jacobian is   
$
    \nabla \vF(\vz) = 
    \begin{bmatrix}
        \nabla^2 f_{\vx\vx}(\vx,\vy) & \nabla^2 f_{\vx \vy}(\vx,\vy) \\
        -\nabla^2 f_{\vx \vy}(\vx,\vy)^\top & -\nabla^2 f_{\vy\vy}(\vx,\vy)
    \end{bmatrix}$.
As noted in~\cite{asl2023j}, $\nabla \vF(\vz)$ exhibits $\mJ$-symmetric structure~\cite{mackey2003structured}, where it is symmetric on the main diagonal blocks and anti-symmetric on the off-diagonal blocks. 
Specifically, for  $
    \mJ = \begin{bmatrix}
        \mI_{m\times m} & 0 \\
        0 & - \mI_{n\times n}
    \end{bmatrix}$,  matrix $\mM$ is $\mJ$-symmetric if $ \mJ\mM$ is symmetric, i.e., $ \mJ \mM = \mM^\top \mJ$. 
Similarly, as discussed in Section~\ref{subsec:nonlinear_eqs}, we can ensure that our Jacobian approximation matrix in our method respects the $\mJ$-symmetry property, simplifying the implementation of some subroutines.  


Specifically, assume that we know the sparsity pattern of the Jacobian matrices, defined as the set
$
  \Omega = \{(i,j):\,\exists\, \vz \in \reals^{d}\,\mathrm{s.t.}\,[\nabla \vF(\vz)]_{ij} \neq 0, \;1\leq i \leq d,\; 1\leq j \leq d\}$,
where $[\nabla \vF(\vz)]_{ij}$ denotes the $(i,j)$-the entry of the matrix $\nabla \vF(\vz)$. 
Moreover, we say a matrix $\mM\in \reals^{d \times d}$ has the sparsity pattern $\Omega$ if $[\mM]_{ij} = 0$ for all $(i,j) \notin \Omega$ and $i \neq j$. 


In the strongly monotone setting (under Assumption~\ref{assum:strong_monotone}), 
recall that there is a unique solution $\vz^*$ to Problem~\eqref{eq:monotone}. Hence, we measure the suboptimality in terms of distance to $\vz^*$. 


\begin{equation}
  \gap_{\text{w}}(\vz; \mathcal{D}) = \max_{\vz' \in \mathcal{D}} \langle \vF(\vz'),   \vz - \vz' \rangle,
\end{equation}

\begin{equation}
  \gap_f(\vz; \vz^*) = f(\vz) - f(\vz^*). 
\end{equation}

\begin{equation}
  \gap_{\text{pd}}(\vz;\calX\times \calY) = \max_{\vy' \in \calY} f(\vx,\vy') - \min_{\vx'\in \calX} f(\vx',\vy),
\end{equation}

where $\vz = (\vx,\vy)$ and $\calX$ and $\calY$ are given compact sets in $\reals^m$ and $\reals^n$, respectively. 


In Lemma~\ref{lem:averaging}, we observe that the gap functions in the three cases can all be upper bounded by a similar quantity. Thus, to unify these different notions, we define  
\begin{equation}\label{eq:gap}
  \gap(\vz; \mathcal{D}) = \begin{cases}
    \gap_{\mathrm{w}}(\vz; \mathcal{D}), & \text{for Problem~\eqref{eq:monotone};}\\
    \max_{\vz' \in \mathcal{D}}\{f(\vz) - f(\vz')\}, & \text{for Problem~\eqref{eq:minimization}};\\
    \max_{(\vx',\vy') \in \calD} \{f(\vx,\vy') - f(\vx',\vy)\}, & \text{for Problem~\eqref{eq:minimax}}.
  \end{cases}
\end{equation}

Specifically, note that $\gap(\vz; \{\vz^*\})$ reduces to $\gap_f(\vz;\vz^*)$ for Problem~\eqref{eq:minimization} and $\gap(\vz; \calX\times \calY)$ reduces to $\gap_{\text{pd}}(\vz;\calX\times \calY)$ for Problem~\eqref{eq:minimax}. 


\begin{algorithm}[t!]\small
  \caption{Quasi-Newton Proximal Extragradient (QNPE) Method (informal)}\label{alg:Full_Equasi-Newton}
    \begin{algorithmic}[1]
        \STATE \textbf{Input:} strong monotonicity parameter $\mu \geq 0$, Jacobian feasible set $\mathcal{Z}$, line search parameters $\alpha_1\geq 0$ and $\alpha_2>0$ such that $\alpha_1+\alpha_2 < 1$,  and initial trial step size $\sigma_0>0$ 
        \STATE \textbf{Initialization:} initial point $\vz_0\in \mathbb{R}^d$ and initial Jacobian approximation $\mB_0\in \mathcal{Z}$ %
        %
        \FOR{iteration $k=0,\ldots,N-1$}
        %
        %
        \STATE Let $\eta_k$ be the largest possible step size in $\{\sigma_k\beta^i:i\geq 0\}$ such that  \tikzmark{top} 
        %
        \begin{gather*}
          \hspace{-8em}\|{\hat{\vz}_k}-\vz_k+{\eta_k}(\vF(\vz_k)+\mB_k({\hat{\vz}_k}-\vz_k))\| \leq \alpha_1 \sqrt{1+\eta_k \mu} \|\hat{\vz}_k-\vz_k\|, \tikzmark{right} %
          \\
          \hspace{-8em}\|\hat{\vz}_k - \vz_k + \eta_k \vF(\hat{\vz}_k)\| \leq { (\alpha_1+\alpha_2)\sqrt{1+\eta_k \mu} \|{\hat{\vz}_k}-\vz_k\|}
           %
      \end{gather*}%

%
        \STATE Set $\sigma_{k+1} \leftarrow \eta_{k}/\beta$ \tikzmark{bottom}
        \STATE Update 
        $
          \vz_{k+1} \leftarrow \theta_k (\vz_k - \eta_k \vF(\hat{\vz}_k))+(1-\theta_k) \hat{\vz}_k
        $, where $\theta_k = \frac{1}{1+2\eta_k\mu}$
        %
        %
        \IF[Line search accepted the initial trial step size]{$\eta_k = \sigma_k$ \tikzmark{top2}}
        \STATE Set $\mB_{k+1} \leftarrow \mB_k$ \label{line:Hessian_approx_unchanged}
        \ELSE[Line search bactracked]
        \STATE Let $\tilde{\vz}_k$ be the last rejected iterate in the line search  %
        \STATE Set $\vu_k \leftarrow \vF(\tilde{\vz}_k) -\vF({\vz_k})$, $\vs_k \leftarrow \tilde{\vz}_k-\vz_k$
        \STATE Define the loss function $\ell_k(\mB) = \frac{\|\vu_k-\mB\vs_k\|^2}{\|\vs_k\|^2}$ 
        \STATE Feed $\ell_k(\mB)$ to an online learning algorithm $\mathcal{A}$ and obtain $\mB_{k+1}$ \quad \tikzmark{right2}
        \ENDIF \tikzmark{bottom2}
        \ENDFOR

    \end{algorithmic}
    \AddNote{top}{bottom}{right}{\hspace{-.5em}\color{comment}\textit{\quad Line search subroutine;\\
             \hspace{.2em} see Section~\ref{subsec:ls}}}
    \AddNote{top2}{bottom2}{right2}{\hspace{-.5em}\color{comment}\textit{\quad Jacobian approximation\\ \hspace{.2em} update subroutine; see \\
    \hspace{.2em} Section~\ref{sec:jacobian_online_learning}}}
    %
  \end{algorithm}

\begin{align}
    \|{\hat{\vz}_k}-\vz_k+{\eta_k}(\vF(\vz_k)+\mB_k({\hat{\vz}_k}-\vz_k))\| &\leq {\alpha_1} \sqrt{1+\eta_k \mu} \|\hat{\vz}_k-\vz_k\|, \label{eq:inexact_linear_solver} \\
    \|\hat{\vz}_k - \vz_k + \eta_k \vF(\hat{\vz}_k)\| &\leq {(\alpha_1+\alpha_2) \sqrt{1+\eta_k \mu} \|{\hat{\vz}_k}-\vz_k\|} \label{eq:inexact_proximal_point}, 
%
\end{align}

where $\alpha_1\in [0,1)$ and $\alpha_2 \in (0,1)$ are user-specified parameters with $\alpha_1+\alpha_2<1$.  


\begin{equation}\label{eq:extragradient_mixing}
%
  \vz_{k+1} = \theta_k(\vz_k - \eta_k \vF(\hat{\vz}_k))+(1-\theta_k)\hat{\vz}_k,
\end{equation}

where $\theta_k \in [0,1]$ is chosen based on our convergence analysis. Specifically, in the monotone setting (under Assumption~\ref{assum:monotone}), we choose $\theta_k = 1$ and \eqref{eq:extragradient_mixing} reduces to the extragradient step in \eqref{eq:extragradient}. Moreover, in the strongly monotone setting (under Assumption~\ref{assum:strong_monotone}), we choose $\theta_k  = \frac{1}{1+2\eta_k\mu}$.


\begin{algorithmic}[1]
      \STATE \textbf{Input:} iterate $\vz \in \mathbb{R}^d$,  operator $\vg\in \reals^d$,  Jacobian approximation $\mB$, initial trial step size $\sigma>0$
      \STATE \textbf{Parameters:} line search parameters $\beta\in (0,1)$, $\alpha_1\geq 0$ and $\alpha_2>0$ such that $\alpha_1+\alpha_2<1$
      %
      \STATE Set ${\eta}_{+} \leftarrow \sigma$, {$\vs_{+} \leftarrow \mathsf{LinearSolver}(\mI+\eta_{+}\mB, -\eta_{+}\vg; {\alpha_1}\sqrt{1+\eta_+ \mu})$ and $\hat{\vz}_{+} \leftarrow \vz+\vs_{+}$}
      \WHILE{$\|\hat{\vz}_+ - \vz + \eta_+ \vF(\hat{\vz}_+)\| \geq (\alpha_1+\alpha_2)\sqrt{1+\eta_+ \mu} \|{\hat{\vz}_{+}}-\vz\|$\label{line:check_condition}}
        \STATE Set $\tilde{\vz} \leftarrow \hat{\vz}_{+}$ %
          and $\eta_{+} \leftarrow \beta\eta_+ $ \label{line:decreasing_stepsize}
      \STATE Compute $\vs_{+} \leftarrow \mathsf{LinearSolver}(\mI+\eta_{+}\mB, -\eta_{+}\vg; \alpha_1\sqrt{1+\eta_+ \mu})$ and $\hat{\vz}_{+} \leftarrow \vz+\vs_{+}$
      \ENDWHILE
      \IF{$\eta_+ = \sigma$}
      \STATE \textbf{Return} $\eta_{+}$ and  $\hat{\vz}_{+}$ \label{line:return_1}
      \ELSE 
      \STATE \textbf{Return} $\eta_{+}$, $\hat{\vz}_{+}$ and $\tilde{\vz}$ \label{line:return_2}
      \ENDIF
  \end{algorithmic}

Next, we present the backtracking line search scheme for selecting $\eta_k$ and the iterate $\hat{\vz}_k$ in the first stage of QNPE. For brevity, we denote $\vF(\vz_k)$ by $\vg$ and omit the iteration subscript $k$ from both $\vz_k$ and $\mB_k$. %
In light of \eqref{eq:inexact_linear_solver} and \eqref{eq:inexact_proximal_point}, our goal at the $k$-th iteration is to identify a pair $(\eta_{+}, \hat{\vz}_{+})$ satisfying  
%
\begin{align}
  %
  \|\hat{\vz}_{+}-\vz+{\eta_{+}}(\vg+\mB({\hat{\vz}_{+}}-\vz))\| &\leq  {\alpha_1}\sqrt{1+\eta_+ \mu} \|{\hat{\vz}_{+}}-\vz\|,
  \label{eq:x_plus_update} \\
  \|\hat{\vz}_+ - \vz + \eta_+ \vF(\hat{\vz}_+)\| &\leq (\alpha_1+\alpha_2)\sqrt{1+\eta_+ \mu} \|{\hat{\vz}_{+}}-\vz\|  \label{eq:step size_condition}. 
\end{align}

As previously discussed, with $\eta_{+}$ fixed, the first condition in \eqref{eq:x_plus_update} can be met by solving the linear system $(\mI+\eta_{+}\mB)(\hat{\vz}_+-\vz) = -\eta_+\vg$ to a desired accuracy.


\begin{equation}\label{eq:linear_solver_update}
  \vs_{+} = \mathsf{LinearSolver}(\mI+\eta_{+}\mB, -\eta_{+}\vg; {\alpha_1}\sqrt{1+\eta_+ \mu}) \quad \text{and} \quad \hat{\vz}_{+} = \vz+\vs_{+},
  %
\end{equation}

where the $\mathsf{LinearSolver}$ oracle is defined as follows. %


\begin{definition}\label{def:linear_solver}
  The oracle $\mathsf{LinearSolver}(\mA,\vb; \rho)$ takes  a matrix $\mA \in \reals^{d\times d}$, a vector $\vb\in \reals^d$ and $\rho>0$ as input, and returns an approximate solution $\vs_{+}$ 
  %
  satisfying $\|\mA\vs_{+}-\vb\| \leq \rho \|\vs_{+}\|$. 
  %
  %
  %
  %
  %
  %
\end{definition}

Recall that $\calB$ is the set of indices where the line search subroutine backtracks, i.e., $\calB = \{k: \eta_k < \sigma_k\}$. 


Formally, define the loss function $\ell_k : \reals^{d \times d} \rightarrow \reals$ at iteration $k$ as


\begin{equation}\label{eq:loss_of_jacobian}
  \ell_k(\mB) \triangleq 
  \begin{cases}
    0, & \text{if } k\notin \mathcal{B}, \\
    \frac{\|\vu_k-\mB\vs_k\|^2}{\|\vs_k\|^2}, & \text{otherwise}.
  \end{cases}
  %
\end{equation}

Given these points and the discussions in Section~\ref{subsec:structures}, we choose the feasible set~$\calZ$ as follows: 
\begin{enumerate}[(a)]
  \item For the minimization problem in \eqref{eq:minimization}, we choose 


\begin{equation}\label{eq:feasible_set_min}
    \calZ = \{\mB \in \sS^d: \; \mu \mI \preceq \mB \preceq L_1 \mI,\; \mB \in \calL\},
  \end{equation}

  where $\calL \subset \sS^d$ is a linear subspace. in the general case, we set $\calL = \sS^d$. However, when the Hessians of $f$ exhibit the sparsity pattern $\Omega$, we define $\calL$ as $\calL=\{\mB\in \sS^{d}: [\mB]_{ij} = 0 \text{ for all } (i,j)\notin \Omega \text{ and }i\neq j\}$.
  \item For the minimax problem in \eqref{eq:minimax} and the nonlinear equation in \eqref{eq:monotone}, we choose 


\begin{equation}\label{eq:feasible_set}
    \mathcal{Z} = \left\{ \mB \in \reals^{d\times d}:\mu \mI \preceq \frac{1}{2}(\mB + \mB^\top )\preceq L_1\mI , \;\|\mB\|_{\op} \leq L_1, \mB \in \mathcal{L} \right\},
    %
  \end{equation}

  where $\mathcal{L} \subset \reals^{d\times d}$ is a linear subspace. For general nonlinear equations $\mathcal{L} = \reals^{d \times d}$, for minimax problems $\mathcal{L} = \{\mB\in \reals^{d\times d}: \mB = \mJ \mB^\top \mJ\}$, and for sparse nonlinear equations $\calL=\{\mB\in \reals^{d\times d}: [\mB]_{ij} = 0 \text{ for all } (i,j)\notin \Omega \text{ and }i\neq j\}$.
\end{enumerate}


\begin{algorithm}[!t]\small
  \caption{Projection-Free Online Learning}\label{alg:projection_free_online_learning}
  \begin{algorithmic}[1]
      \STATE \textbf{Input:} Initial point $\vw_0 \in  \vspan(\calC)$, the orthogonal projection matrix $\mP$ associated with the subspace $\vspan(\calC)$, step size $\rho>0$, $\delta>0$, radius $R>0$
      %
      %
      \FOR{$t=0,1,\dots T-1$}
      \STATE Query the oracle $(\gamma_t,\vs_t) \leftarrow \mathsf{SEP}_{\calC}(\vw_t;\delta)$
      \IF[Case I: we have $\vw_t\in (1+\delta)\mathcal{C}$]{$\gamma_t \leq 1$}
      %
      %
        \STATE Set $\vx_t \leftarrow \begin{cases} \vw_t & (\textbf{Option I}) \\ \frac{\vw_t}{1+\delta} & (\textbf{Option II}) \end{cases}$ and play the action $\vx_t$ 
        \STATE Receive the loss $\ell_t(\vx_t)$ and the subspace gradient $\vg_t = \mP\nabla \ell_t(\vx_t)$
        \STATE Set $\tilde{\vg}_t \leftarrow \vg_t$
      %
      %
      \ELSE[Case II: we have $\vw_t/\gamma_t\in (1+\delta)\mathcal{C}$] 
      %
        \STATE Set $\vx_t \leftarrow \begin{cases} \frac{\vw_t}{\gamma_t} & (\textbf{Option I}) \\ \frac{\vw_t}{(1+\delta)\gamma_t} & (\textbf{Option II}) \end{cases}$ and play the action $\vx_t$ 
      \STATE Receive the loss $\ell_t(\vx_t)$ and the subspace gradient $\vg_t = \mP\nabla \ell_t(\vx_t)$
      \STATE Set $\tilde{\vg}_t \leftarrow \vg_t+\max\left\{0, - \frac{1}{\gamma_t}\langle \vg_t, \vw_t \rangle\right\} \vs_t$
      %
      \ENDIF
      %
      \STATE Update $\vw_{t+1} \leftarrow \frac{R(\vw_t-\rho \tilde{\vg}_t)}{\max\{\|\vw_t-\rho \tilde{\vg}_t\|_2,R\}} $ 
      \COMMENT{Online projected gradient descent}
      \ENDFOR
  \end{algorithmic}
\end{algorithm}

To set the stage for our Jacobian approximation update algorithm, we take a detour and consider a general online learning problem over a compact feasible set $\calC \subset \reals^D$. For $T$ consecutive rounds $t=0,\dots,T-1$, a learner chooses an action $\vx_t \in \reals^D$ and then observes a convex loss function $\ell_t:\reals^D \rightarrow \reals$. 
\blue{The goal is to minimize either the \emph{static regret} defined by $\mathrm{Reg}_T(\vu; \calC) \triangleq \sum_{t=0}^{T-1} \ell_t(\vx_t) - \sum_{t=0}^{T-1} \ell_t(\vu)$ with a fixed competitor $\vx \in \calC$, or the \emph{dynamic regret} defined by $\dreg_T(\vu_0,\dots,\vu_{T-1}; \calC) \triangleq \sum_{t=0}^{T-1} \ell_t(\vx_t) - \sum_{t=0}^{T-1} \ell_t(\vu_t)$ with a sequence of competitors $\vu_t \in \calC$ for any $t \geq 0$.}
We assume $0\in \mathcal{C}$ without loss of generality. Moreover, we assume that the set $\calC$ is contained in the Euclidean ball $B_R(0):= \{\vw\in \reals^D: \|\vw\|\leq R\}$ for some radius $R>0$.


To start, we will define the approximate separation oracle $\SEP_{\cal{C}}$ for a compact set $\calC$. We use $\vspan(\mathcal{C})$ to denote the linear span of $\mathcal{C}$, i.e., $\vspan(\calC) = \left\{\sum_{i=1}^{k}  \alpha_i \vx_i : k \in \mathbb{Z}_+,\;\vx_i \in \calC,\; \alpha_i \in \reals  \right\}$. Intuitively, $\vspan(\calC)$ is the smallest linear subspace that contains the set $\calC$. %


\begin{definition}\label{def:gauge}
  Let $\calC$ be a compact convex set in $\reals^D$ containing the origin. 
  The oracle $\mathsf{SEP}_{\mathcal{C}}(\vw; \delta)$ takes $\vw\!\in\! \vspan(\calC)$ and $\delta>0$ and returns $\gamma>0$ and a vector $\vs\in \vspan(\calC)$ with one of these outcomes:
   %
   %
    \begin{itemize}
      \item Case I: $\gamma \leq 1$, which implies that $\vw \in (1+\delta)\mathcal{C}$;
       %
      \item Case II: $\gamma>1$, which implies that $\vw/\gamma \in (1+\delta)\mathcal{C} \ $ and $\ \langle \vs, \vw-\vx \rangle \geq {\gamma-1},$  $ \forall\vx\in \mathcal{C}$. 
    \end{itemize}
    %
    %
    %
    %
    %
    \end{definition}

\begin{equation}\label{eq:w_update}
  \vw_{t+1}  = \mathrm{\Pi}_{\mathcal{B}_R(0)}\bigl(\vw_t-\rho \nabla \tilde{\ell}_t(\vw_t)\bigr) = \frac{R}{\max\{\|\vw_t-\rho \tilde{\vg}_t\|_2,R\}} (\vw_t-\rho \tilde{\vg}_t).
\end{equation}

\begin{algorithmic}[1]
      \STATE \textbf{Input:} Initial matrix $\mB_0\in \mathcal{Z}$, the orthogonal projection matrix $\mP$, step size $\rho>0$, $\delta>0$, failure probabilities $\{q_t\}_{t=1}^{T-1}$, Lipschitz constant $L_1>0$ and strong monotonicity parameter $\mu \geq 0$
      \STATE \textbf{Initialize:} set $\mW_0 \leftarrow \frac{1}{L_1}(\mB-(L_1+\mu)\mI)$, $\mG_0 \leftarrow \frac{1}{L_1} \mP\nabla \ell_0(\mB_0)$ and $\tilde{\mG}_0 \leftarrow \mG_0$
      \STATE {Update $\mW_{1} \leftarrow \frac{\sqrt{d}(\mW_0 - \rho \tilde{\mG}_0)}{\max\{\sqrt{d},\|\mW_0 - \rho \tilde{\mG}_0\|_F\}}$ \COMMENT{Projection onto $\mathcal{B}_{\sqrt{d}}(0)$}\vspace{-.5em}
      \FOR{$t=1,\dots,T-1$}
      \STATE Query $(\gamma^{(1)}_t,\mS^{(1)}_t) \leftarrow \mathsf{ExtEvec}(\frac{\mW_t+\mW_t^\top}{2};\delta, \frac{q_t}{2} )$ and $(\gamma^{(2)}_t,\mS^{(2)}_t) \leftarrow \mathsf{MaxSvec}(\mW_t;\delta, \frac{q_t}{2} )$ %
      \STATE Let $i = \argmax_{i\in \{1,2\}} \gamma_t^{(i)}$, and set $\gamma_t \leftarrow \gamma_t^{(i)}$ and $\mS_t \leftarrow \mP \mS_t^{(i)}$
      \IF[Case I]{$\gamma_t \leq 1$}
      %
        \STATE Set $\hat{\mB}_t \leftarrow \begin{cases} \mW_t & \text{if }\mu>0\;(\textbf{Option I})\\ \frac{\mW_t}{1+\delta} & \text{if }\mu=0\; (\textbf{Option II})\end{cases}$ and $\mB_t \leftarrow {L_1}\hat{\mB}_t+{(L_1+\mu)}\mI$
        \STATE Set $\mG_t \leftarrow \frac{1}{L_1}\mP\nabla \ell_t(\mB_t)$ and $\tilde{\mG}_t \leftarrow \mG_t$
        %
      \ELSE[Case II]
        \STATE Set $\hat{\mB}_t \leftarrow \begin{cases} \frac{\mW_t}{\gamma_t} & \text{if }\mu>0\;(\textbf{Option I})\\ \frac{\mW_t}{(1+\delta)\gamma_t} & \text{if }\mu=0\; (\textbf{Option II})\end{cases}$ and $\mB_t \leftarrow {L_1}\hat{\mB}_t+{(L_1+\mu)}\mI$ 
        \STATE Set $\mG_t \leftarrow \frac{1}{L_1}\mP\nabla \ell_t(\mB_t)$ and $\tilde{\mG}_t \leftarrow \mG_t+\max\{0,-\frac{1}{\gamma_t}\langle \mG_t, \mW_t \rangle\} \mS_t$
        %
      \ENDIF
      %
      %
      %
      %
      %
      %
      %
      %
      %
      %
      %
      %
      %
      %
      %
      %
      \STATE %
      %
      Update 
      $\mW_{t+1} \leftarrow \frac{\sqrt{d}(\mW_t - \rho \tilde{\mG}_t)}{\max\{\sqrt{d},\|\mW_t - \rho \tilde{\mG}_t\|_F\}}$ \COMMENT{Projection onto $\mathcal{B}_{\sqrt{d}}(0)$}
        %
        %
        %
        %
      %
      \ENDFOR}
  \end{algorithmic}

Next, we present our online learning algorithm for updating $\{\mB_k\}_{k \geq 0}$. We follow the projection-free online learning algorithm outlined in Section~\ref{subsec:projection_free_online_learning} and apply it to the online learning problem in Section~\ref{subsec:convergence}.
\blue{Moreover, recall that $\calB$ denotes the set of indices where the line search subroutine backtracks, and we have $\ell_k(\mB)=0$ when $k\notin \mathcal{B}$. Thus, we can simply keep $\mB_{k+1}$ unchanged for these iterations (cf. Line~\ref{line:Hessian_approx_unchanged} in Algorithm~\ref{alg:Full_Equasi-Newton}). Suppose $\calB = \{k_0,k_1,\dots,k_{T-1}\}$, where $T \leq N$. With a slight abuse of notation, in the following, we relabel the indices in $\mathcal{B}$ as $t=0,\dots,T-1$.}

The remaining question is how to construct the approximate separation oracle, required by the projection-free scheme and defined in Definition~\ref{def:gauge}, for our specific set $\calZ$.
To start, we consider the nonlinear monotone equation in \eqref{eq:monotone}; we will further discuss the special cases in the next section.  
Recall that the feasible set~$\calZ$ for our online learning problem in Section~\ref{subsec:convergence} is given in \eqref{eq:feasible_set} with a linear subspace $\calL$. In the following, we assume that the orthogonal projection matrix $\mP$ associated with the linear subspace $\calL$ is given. Specifically, for a general nonlinear monotone equation, we have $\calL = \reals^d$ and the matrix $\mP$ is simply the identity matrix. Moreover, for those special cases discussed in Section~\ref{subsec:structures}, the linear subspace is specified at the end of Section~\ref{subsec:convergence} and we will discuss the corresponding projection matrix in Section~\ref{subsec:special_cases}. 


Hence, we will work with the new set $\calC$ in our online learning algorithm. Moreover, note that we can write $\calC = \calC_1 \cap \calC_2 \cap \calL$, where we define 
%
  $\mathcal{C}_1 \mydef \{\hat{\mB} \in \mathbb{R}^{d\times d}:  -\mI \preceq \frac{1}{2}(\hat{\mB} + \hat{\mB}^\top )\preceq \mI \}$ and $\mathcal{C}_2 \mydef \{\hat{\mB} \in \mathbb{R}^{d\times d}: \|\hat{\mB}\|_{\op} \leq 3 \}$.  


\begin{definition}\label{def:extevec}
  The oracle $\mathsf{ExtEvec}(\mW;\delta,q)$ takes $\mW \in \reals^{d\times d}$, $\delta>0$, and $q\in (0,1)$ as input and returns a scalar $\gamma>0$ and a matrix $\mS\in \mathbb{S}^d$. With probability at least $1-q$, the returned $\gamma$ and $\mS$ satisfy one of the following properties::
  %
  \begin{itemize}
    \item Case I: $\gamma \leq 1$, which implies that
    %
    $-(1+\delta)\mI \preceq \frac{1}{2}(\mW+\mW^\top) \preceq (1+\delta)\mI$;
    %
    \item Case II: $\gamma>1$, which implies that %
    %
    $-(1+\delta)\mI \preceq \frac{1}{2\gamma}(\mW+\mW^\top) \preceq (1+\delta)\mI$, 
    $\|\mS\|_F \leq 1$ and $\langle \mS,\mW-\hat{\mB}\rangle \geq \gamma -1$ for any $\hat{\mB}$ such that $-\mI \preceq \frac{1}{2}(\hat{\mB}+\hat{\mB}^\top) \preceq \mI$.
  \end{itemize}
%
%
%
%
%
%
\end{definition}

\begin{definition}\label{def:MaxSvec}
  The oracle $\mathsf{MaxSvec}(\mW;\delta,q)$ takes $\mW \in \mathbb{R}^{d\times d}$, $\delta>0$, and $q\in (0,1)$ as input and returns a scalar $\gamma>0$ and a matrix $\mS\in \mathbb{R}^{d\times d}$. With probability at least $1-q$, the returned $\gamma$ and $\mS$ satisfy one of the following properties::
  %
  \begin{itemize}
    \item Case I: $\gamma \leq 1$, which implies that $ \|\mW\|_{\op} \leq 3(1+\delta) $;
    %
    \item Case II: $\gamma>1$, which implies that $ \|\mW/\gamma \|_{\op} \leq 3(1+\delta)$, $\|\mS\|_F \leq 1$ and $\langle \mS,\mW-\hat{\mB}\rangle \geq \gamma -1$ for any $\hat{\mB} \in \reals^{d\times d}$ such that $ \|\hat{\mB}\|_{\op}  \leq 3 $.
  \end{itemize}
\end{definition}

\begin{algorithmic}[1]
      \STATE \textbf{Input:} $\mW \in \reals^{d\times d}$, $\delta>0$, $q\in (0,1)$
      \STATE \textbf{Initialize:} sample $\vv_1\in \reals^d$ uniformly from the unit sphere, $\beta_1 \leftarrow 0$, $\vv_0\leftarrow 0$
      \STATE Set $\bar{\mW} \leftarrow \frac{1}{2}(\mW + \mW^\top)$ and set the number of iterations 
      $N \leftarrow \Bigl\lceil\frac{1}{4}\sqrt{2(1+\frac{1}{\delta})}\log(\frac{11d}{q^2})+\frac{1}{2} \rceil$
      %
      %
      %
      %
      \FOR{$k=1,\dots,N$ \tikzmark{top}}
      \STATE Set $\vw_k \leftarrow \bar{\mW} \vv_k-\beta_k \vv_{k-1}$ 
      \STATE Set $\alpha_k \leftarrow \langle \vw_k,\vv_k \rangle $ and $\vw_k \leftarrow \vw_k-\alpha_k\vv_k$
      \STATE Set $\beta_{k+1} \leftarrow \|\vw_k\|$ and $\vv_{k+1}\leftarrow \vw_k/\beta_{k+1}$
      \ENDFOR
    \STATE Form a tridiagonal matrix $\mT \leftarrow \mathsf{tridiag}(\beta_{2:N},\alpha_{1:N},\beta_{2:N})$
    \STATE \hspace{-1em}\COMMENT{Use the tridiagonal structure to compute eigenvectors of $\mT$}
    \STATE Compute $(\hat{\lambda}_1,\vz^{(1)}) \leftarrow \mathsf{MaxEvec}(\mT)$ and $(\hat{\lambda}_d, \vz^{(d)}) \leftarrow \mathsf{MinEvec}(\mT)$ \tikzmark{right}
    \STATE Set $\vu^{(1)} \leftarrow \sum_{k=1}^N z^{(1)}_k\vv_k$ and $\vu^{(d)} \leftarrow \sum_{k=1}^N z^{(d)}_k\vv_k$ \tikzmark{bottom}
    \STATE Set $\gamma \leftarrow \max\{\hat{\lambda}_1,-\hat{\lambda}_d\}$ 
    \IF{$\gamma \leq 1$}
    \STATE Return $\gamma$ and $\mS = 0$ \COMMENT{Case I: $\gamma\leq 1$, which implies $\|\mW\|_{\op} \leq 1+\delta$}
    \ELSIF{$\hat{\lambda}_1 \geq -\hat{\lambda}_d$}
      \STATE Return $\gamma$ and $\mS = \vu^{(1)}(\vu^{(1)})^\top$ \hspace{.75em}\COMMENT{Case II: $\gamma> 1$ and $\mS$ defines a separating hyperplane}
    \ELSE
      \STATE Return $\gamma$ and $\mS = -\vu^{(d)}(\vu^{(d)})^\top$ \COMMENT{Case II: $\gamma> 1$ and $\mS$ defines a separating hyperplane}
    \ENDIF
  \end{algorithmic}

\begin{algorithmic}[1]
    \STATE \textbf{Input:} $\mW \in \mathbb{R}^{d\times d}$, $\delta>0$, $q\in (0,1)$
    %
    \STATE Set $\tilde{\mW} \leftarrow \begin{bmatrix} 0 & \mW \\ \mW^\top & 0
    \end{bmatrix} \in \mathbb{S}^{2d}$ and the number of iterations $N  \leftarrow 
    %
    \Bigl\lceil \frac{1}{4}\sqrt{2(1+\frac{1}{\delta})}\log\frac{22d}{q^2}+\frac{1}{2}\Bigr
    \rceil
    %
    $

    \STATE Compute approximate largest eigenvalue $\tilde{\lambda}_1$ and its eigenvector $\tilde{\vv} \in \reals^{2d}$, by running the Lanczos method on $\tilde{\mW}$ for $N$ iterations \COMMENT{See Subroutine~\ref{alg:lanczos}}
    \STATE Partition $\tilde{\vv}$ as $\tilde{\vv} = [\vv,\vv']$ where $\vv, \vv' \in \reals^d$ 
    %
    %
    %
    %
    %
    %
    %
    %
    %
    %
    %
    \STATE Set $\gamma \leftarrow \tilde{\lambda}_1/3$ 
    \IF{$\gamma \leq 1$}
    \STATE Return $\gamma$ and $\mS = 0$ \COMMENT{Case I: $\gamma\leq 1$, which implies $\|\mW\|_{\op} \leq 3(1+\delta)$}
    \ELSE
      \STATE Return $\gamma$ and $\mS = \frac{2}{3}\vv'\vv^\top \in \reals^{d\times d}$ \hspace{.75em}\COMMENT{Case II: $\gamma> 1$ and $\mS$ defines a separating hyperplane}
    %
    %
    \ENDIF
  \end{algorithmic}

