\begin{proof}
Let $\alpha = \alpha_1 + \alpha_2$. First, we prove Part (a). Since $\mF(\vz^*) = 0$ and $\vF$ is $\mu$-strongly monotone by Assumption~\ref{assum:strong_monotone}, it holds that  
\begin{equation}\label{eq:strong_monotone}
\langle \vF(\hat{\vz}_k),\hat{\vz}_k - \vz^* \rangle = \langle \vF(\hat{\vz}_k)-\vF({\vz^*}),\hat{\vz}_k - \vz^* \rangle \geq \mu\|\hat{\vz}_k - \vz^*\|^2.
\end{equation}
By setting $\vz = \vz^*$ in \eqref{eq:one_step} and applying \eqref{eq:strong_monotone}, it yields 
\begin{equation}\label{eq:one_step_strongly}
    0 \leq \frac{1}{2}\|\vz_k- \vz^*\|^2 - \frac{1+2\eta_k\mu}{2}\|\vz_{k+1} - \vz^*\|^2  - \frac{1-\alpha}{2}(\|\hat{\vz}_k - \vz_k\|^2 + \|\hat{\vz}_k-\vz_{k+1}\|^2).
\end{equation} 
Since $\alpha = \alpha_1 + \alpha_2 <1$, we can drop the non-positive last term in \eqref{eq:one_step_strongly} and obtain $0 \leq \frac{1}{2}\|\vz_k- \vz^*\|^2 - \frac{1+2\eta_k\mu}{2}\|\vz_{k+1} - \vz^*\|^2$, which is equivalent to $\|\vz_{k+1} - \vz^*\|^2 \leq \|\vz_k- \vz^*\|^2 (1+2\eta_k\mu)^{-1}$. This completes the proof of Part (a). 

Next, we prove Part (b). Since $\vF$ is monotone by Assumption~\ref{assum:monotone}, we have
  \begin{equation}\label{eq:monotone_star}
    \langle \vF(\hat{\vz}_k),\hat{\vz}_k - \vz^* \rangle = \langle \vF(\hat{\vz}_k)-\vF({\vz^*}),\hat{\vz}_k - \vz^* \rangle \geq 0.
    \end{equation}
    By setting $\vz = \vz^*$ in \eqref{eq:one_step} with $\mu = 0$ and applying \eqref{eq:monotone_star}, it yields 
    \begin{equation}\label{eq:one_step_monotone}
      0 \leq \frac{1}{2}\|\vz_k- \vz^*\|^2 - \frac{1}{2}\|\vz_{k+1} - \vz^*\|^2  - \frac{1-\alpha}{2}(\|\hat{\vz}_k - \vz_k\|^2 + \|\hat{\vz}_k-\vz_{k+1}\|^2).
    \end{equation}
    Again, since the last term in \eqref{eq:one_step_monotone} is non-positive, this immediately implies $\frac{1}{2}\|\vz_{k+1} - \vz^*\|^2 \leq \frac{1}{2}\|\vz_{k} - \vz^*\|^2$, which is equivalent to $\|\vz_{k+1} - \vz^*\| \leq \|\vz_{k} - \vz^*\|$. Additionally, by dropping the non-positive last term in \eqref{eq:one_step} and noting that $\mu = 0$, we also have 
    %
    $\eta_k \langle \vF(\hat{\vz}_k),\hat{\vz}_k - \vz \rangle \leq \frac{1}{2}\|\vz_k- \vz\|^2 - \frac{1}{2}\|\vz_{k+1} - \vz\|^2$.
    %
    By summing this inequality from $k=0$ to $k=N-1$, we further get 
    %
