\begin{lemma}\label{lem:sep_intersect}
  Assume that $\mathcal{C} = \mathcal{C}_1 \cap \mathcal{C}_2 \cap \mathcal{L}$, where $0 \in \calC_1 \cap \calC_2$ and $\mathcal{L}= \vspan(\calC)$ is a linear subspace. Suppose we have access to $\mathsf{SEP}_{\mathcal{C}_1}(\vw; \delta)$, $\mathsf{SEP}_{\mathcal{C}_2}(\vw; \delta)$ and the orthogonal projection matrix $\mP_{\calL}$ associated with the subspace $\calL$. Then given inputs $\vw \in \calL$ and $\delta>0$, the oracle $\mathsf{SEP}_{\mathcal{C}}(\vw; \delta)$ can be constructed in the following ways: 
  \begin{enumerate}[(a)]
  %
    \item  let $(\gamma_1,\vs_1) = \mathsf{SEP}_{\mathcal{C}_1}(\vw; \delta)$ and $(\gamma_2,\vs_2) = \mathsf{SEP}_{\mathcal{C}_2}(\vw; \delta)$.
    %
    \item Let $i = \argmax_{i \in \{1,2\}} \gamma_i$ and then output $(\gamma,\vs) = (\gamma_i,\mP_{\calL}\vs_i)$.
  \end{enumerate}
  %
\end{lemma}

Next, we will prove that $\langle \vs, \vw-\vx \rangle \geq \gamma-1$.  Since $\calC_1 \subset \calC$, we have $\vx \in \calC_1$ for any $\vx \in \calC$. Therefore,  it implies that $\langle \vs_1, \vw - \vx \rangle \geq \gamma_1-1 = \gamma-1$. Moreover, since $\vw \in \calL$ and $\vx \in \calL$, we have $\mP_{\calL}(\vw-\vx) = \vw-\vx$. Therefore, we conclude that $\langle \vs, \vw-\vx \rangle = \langle \mP_{\calL}\vs_1, \vw-\vx \rangle = \langle \vs_1, \mP_{\calL}(\vw-\vx) \rangle = \langle \vs_1, \vw-\vx \rangle \geq \gamma_1 -1 = \gamma-1$. 

Combining both cases, we observe that the procedure described in Lemma~\ref{lem:sep_intersect} indeed satisfies the definition in Definition~\ref{def:gauge}. This completes the proof. 
\end{proof}

