\begin{equation}\label{eq:comparator_3}
 \begin{aligned}
  \sum_{k\in \calB} \|{\vz}_k-\vz^*\|^2 \leq \sum_{k=0}^{N-1} \|\vz_k-\vz^*\|^2 &\leq \|\vz_0-\vz^*\|^2\sum_{k=0}^{N-1} \left(1+\frac{4\alpha_2\beta\mu}{15L_1}\right)^{-k}\\ &\leq  \|\vz_0-\vz^*\|^2\left(1+\frac{15L_1}{4\alpha_2 \beta \mu}\right).
 \end{aligned}
\end{equation}
Lemma~\ref{lem:comparator} follows immediately from \eqref{eq:comparator_1}, \eqref{eq:comparator_2}, and \eqref{eq:comparator_3}. 
  \end{proof}

Therefore, we have $\|\vu_t-\mH^*\vs_t\| = \|(\bar{\mH}_t-\mH^*)\vs_t\| \leq \|\bar{\mH}_t-\mH^*\|_{\op}\|\vs_t\| \leq L_2\|\vs_t\|\Bigl(\|\vz_t-\vz^*\|+\frac{1}{2}\|\vs_t\|\Bigr)$. This further implies that 
\begin{align}
  \sum_{t=0}^{T-1} \ell_t(\mH^*) = \sum_{t=0}^{T-1} \frac{\|\vu_t-\mH^*\vs_t\|^2}{\|\vs_t\|^2} &\leq {L_2^2}\sum_{t=0}^{T-1}\Bigl(\|\vz_t-\vz^*\|+\frac{1}{2}\|\vs_t\|\Bigr)^2 \nonumber\\ 
  &\leq \frac{L_2^2}{2} \sum_{t=0}^{T-1} \|\vs_t\|^2 + 2 L_2^2\sum_{t=0}^{T-1} \|{\vz}_t-\vz^*\|^2. \label{eq:comparator_1}
\end{align}
\blue{Note that by our notation, we have $\sum_{t=0}^{T-1} \|\vs_t\|^2 = \sum_{k \in \calB} \|\vs_k\|^2 = \sum_{k \in \calB} \|\tilde{\vz}_k - \vz_k\|^2 $ and $\sum_{t=0}^{T-1} \|{\vz}_t-\vz^*\|^2 = \sum_{k\in \calB} \|{\vz}_k-\vz^*\|^2$.}

To bound the first sum $\sum_{k \in \calB} \|\tilde{\vz}_k - \vz_k\|^2$, we use the last result in Lemma~\ref{lem:step size_lb} and the inequality in Lemma~\ref{lem:sum_of_squares} to get 
\begin{equation}\label{eq:comparator_2}
  \begin{aligned}
    \sum_{k\in \calB} \|\tilde{\vz}_k-\vz_k\|^2  \leq \frac{(1+\alpha_1)^2}{\beta^2 (1-\alpha_1)^2} \sum_{k\in \calB} \|\hat{\vz}_k-\vz_k\|^2 
    %
    %
    &\leq \frac{(1+\alpha_1)^2}{\beta^2 (1-\alpha_1)^2} \sum_{k=0}^{N-1} \|\hat{\vz}_k-\vz_k\|^2 \\
      &\leq \frac{(1+\alpha_1)^2\|\vz_0-\vz^*\|^2}{(1-\alpha_1)^2\beta^2 (1-(\alpha_1+\alpha_2))} = 2C \|\vz_0-\vz^*\|^2. 
  \end{aligned}
  %
\end{equation}

To bound the second sum $\sum_{k\in \calB} \|{\vz}_k-\vz^*\|^2$, we use the linear convergence result in Part (a) of Theorem~\ref{thm:main}:
\begin{equation}\label{eq:comparator_3}
 \begin{aligned}
  \sum_{k\in \calB} \|{\vz}_k-\vz^*\|^2 \leq \sum_{k=0}^{N-1} \|\vz_k-\vz^*\|^2 &\leq \|\vz_0-\vz^*\|^2\sum_{k=0}^{N-1} \left(1+\frac{4\alpha_2\beta\mu}{15L_1}\right)^{-k}\\ &\leq  \|\vz_0-\vz^*\|^2\left(1+\frac{15L_1}{4\alpha_2 \beta \mu}\right).
 \end{aligned}
\end{equation}
Lemma~\ref{lem:comparator} follows immediately from \eqref{eq:comparator_1}, \eqref{eq:comparator_2}, and \eqref{eq:comparator_3}. 
  \end{proof}

\begin{lemma}\label{lem:ls_terminates}
  Suppose Assumption~\ref{assum:operator_lips} holds. If ${\eta}_+ <\frac{\alpha_2}{L_1+\|\mB\|_{\op}}$ and $\hat{\vz}_+$ is computed according to \eqref{eq:linear_solver_update}, then the pair $({\eta}_+,\hat{\vz}_+)$ satisfies the conditions in \eqref{eq:x_plus_update} and \eqref{eq:step size_condition}. 
\end{lemma}

\begin{proof}
  Since $\hat{\vz}_+$ follows the update rule in \eqref{eq:linear_solver_update}, 
  by Definition~\ref{def:linear_solver}, the pair $({\eta}_+,\hat{\vz}_+)$ will always satisfy the condition in \eqref{eq:x_plus_update}. 
  %
  Hence, it is sufficient to prove that the condition in \eqref{eq:step size_condition} also holds. 
  Recall that $\vg$ is defined as $\vg = \vF(\vz)$. By Assumption~\ref{assum:operator_lips}, the operator $\vF$ is $L_1$-Lipschitz and thus it follow that  
  %
  $\|\vF(\hat{\vz}_+)-\vg\| = \|\vF(\hat{\vz}_+)-\vF(\vz)\| \leq L_1 \|\hat{\vz}_+ - \vz\|$. 
  %
  Further, applying the triangle inequality yields 
  \begin{equation*}
      \|\vF(\hat{\vz}_+)-\vg-\mB(\hat{\vz}_+-\vz)\| \leq \|\vF(\hat{\vz}_+)-\vg\| + \|\mB(\hat{\vz}_+-\vz)\| \leq (L_1  + \|\mB\|_{\op}) \|\hat{\vz}_+ - \vz\|.
  \end{equation*}
  Hence, if ${\eta}_+ \leq \frac{\alpha_2}{L_1+\|\mB\|_{\op}}$, we have 
     \begin{equation}\label{eq:approx_error}
         {\eta}_+ \|\vF(\hat{\vz}_+)-\vg-\mB(\hat{\vz}_+-\vz)\| \leq \alpha_2 \|\hat{\vz}_+ - \vz\|.
     \end{equation}
  Finally, by using the triangle inequality again,  we combine \eqref{eq:x_plus_update} and \eqref{eq:approx_error} to establish that  
  \begin{align*}
      \|\hat{\vz}_{+}-\vz+{\eta}_+ \vF(\hat{\vz}_{+})\| &= \|\hat{\vz}_{+}-\vz+{{\eta}_+}(\vg+\mB({\hat{\vz}_{+}}-\vz)) + {\eta}_+(\vF(\hat{\vz}_+)-\vg-\mB(\hat{\vz}_+-\vz))\| \\
      &\leq \|\hat{\vz}_{+}-\vz+{{\eta}_+}(\vg+\mB({\hat{\vz}_{+}}-\vz))\| + \|{\eta}_+(\vF(\hat{\vz}_+)-\vg-\mB(\hat{\vz}_+-\vz))\| \\
      &\leq \alpha_1 \sqrt{1+\eta_+ \mu}\|\hat{\vz}_+-\vz\|+\alpha_2 \|\hat{\vz}_+-\vz\| \\
      &\leq (\alpha_1+\alpha_2)\sqrt{1+\eta_+ \mu}\|\hat{\vz}_+-\vz\|, 
  \end{align*}
  which confirms that the condition in \eqref{eq:step size_condition} is satisfied. This completes the proof. 
  \end{proof}

%
Further, applying the triangle inequality yields 
\begin{equation*}
    \|\vF(\hat{\vz}_+)-\vg-\mB(\hat{\vz}_+-\vz)\| \leq \|\vF(\hat{\vz}_+)-\vg\| + \|\mB(\hat{\vz}_+-\vz)\| \leq (L_1  + \|\mB\|_{\op}) \|\hat{\vz}_+ - \vz\|.
\end{equation*}
Hence, if ${\eta}_+ \leq \frac{\alpha_2}{L_1+\|\mB\|_{\op}}$, we have 
   \begin{equation}\label{eq:approx_error}
       {\eta}_+ \|\vF(\hat{\vz}_+)-\vg-\mB(\hat{\vz}_+-\vz)\| \leq \alpha_2 \|\hat{\vz}_+ - \vz\|.
   \end{equation}

Finally, by using the triangle inequality again,  we combine \eqref{eq:x_plus_update} and \eqref{eq:approx_error} to establish that  
\begin{align*}
    \|\hat{\vz}_{+}-\vz+{\eta}_+ \vF(\hat{\vz}_{+})\| &= \|\hat{\vz}_{+}-\vz+{{\eta}_+}(\vg+\mB({\hat{\vz}_{+}}-\vz)) + {\eta}_+(\vF(\hat{\vz}_+)-\vg-\mB(\hat{\vz}_+-\vz))\| \\
    &\leq \|\hat{\vz}_{+}-\vz+{{\eta}_+}(\vg+\mB({\hat{\vz}_{+}}-\vz))\| + \|{\eta}_+(\vF(\hat{\vz}_+)-\vg-\mB(\hat{\vz}_+-\vz))\| \\
    &\leq \alpha_1 \sqrt{1+\eta_+ \mu}\|\hat{\vz}_+-\vz\|+\alpha_2 \|\hat{\vz}_+-\vz\| \\
    &\leq (\alpha_1+\alpha_2)\sqrt{1+\eta_+ \mu}\|\hat{\vz}_+-\vz\|, 
\end{align*}
which confirms that the condition in \eqref{eq:step size_condition} is satisfied. This completes the proof. 
\end{proof}

In light of Lemma~\ref{lem:stepsize_const_bound}, it follows from Proposition~\ref{prop:HPE}(a) that  $\|\vz_{k+1}-\vz^*\|^2 \leq \|\vz_k-\vz^*\|^2 (1+2\eta_k \mu)^{-1} \leq \|\vz_k-\vz^*\|^2 \left(1+\frac{4\alpha_2\beta\mu}{15L_1}\right)^{-1}$. 
This proves the linear convergence result in (a). 
\end{proof}
